const ROOM_RE = /^[A-Z2-9]{8}$/;
const ROLES = new Set(["desktop", "mobile", "browser"]);

const INDEX_HTML = "<!doctype html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#0b7a33\">\n  <meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n  <meta name=\"apple-mobile-web-app-status-bar-style\" content=\"default\">\n  <meta name=\"apple-mobile-web-app-title\" content=\"UniScan\">\n  <meta name=\"description\" content=\"UniScan - حوّل هاتفك إلى قارئ باركود لاسلكي لأي حاسبة.\">\n  <link rel=\"manifest\" href=\"/manifest.webmanifest\">\n  <link rel=\"apple-touch-icon\" href=\"/icons/icon-192.png\">\n  <link rel=\"icon\" href=\"/icons/icon-192.png\">\n  <link rel=\"stylesheet\" href=\"/styles.css\">\n  <title>UniScan</title>\n</head>\n<body>\n  <main class=\"app\">\n    <header class=\"topbar\">\n      <div class=\"brand\">\n        <img src=\"/logo.png\" alt=\"UniScan logo\">\n        <div class=\"brand-copy\"><h1>UniScan</h1><div class=\"credit\"><span>تطوير: مصطفى محمد</span><span class=\"credit-dot\">•</span><a href=\"https://wa.me/9647801252217\" target=\"_blank\" rel=\"noopener\">واتساب: 07801252217</a></div></div>\n      </div>\n      <span id=\"connPill\" class=\"pill\">غير مرتبط</span>\n    </header>\n\n    <section class=\"card pair-card\" id=\"pairCard\">\n      <div>\n        <h2>ربط الحاسبة</h2>\n        <p class=\"muted\">امسح QR الذي يظهره UniScan على الحاسبة، أو اكتب كود الربط.</p>\n      </div>\n      <div class=\"pair-row\">\n        <input id=\"pairCode\" maxlength=\"8\" autocapitalize=\"characters\" autocomplete=\"off\" placeholder=\"مثال: K7M2P9Q4\">\n        <button id=\"pairBtn\" class=\"primary\">ربط</button>\n      </div>\n      <div id=\"pairMsg\" class=\"hint\">بانتظار كود الربط.</div>\n    </section>\n\n    <section class=\"card scan-card\">\n      <div class=\"camera-shell\">\n        <div id=\"reader\"></div>\n        <div class=\"scan-frame\"><i></i></div>\n        <div id=\"cameraStatus\" class=\"camera-status\">الكاميرا متوقفة</div>\n      </div>\n      <div class=\"controls\">\n        <button id=\"startBtn\" class=\"primary grow\">تشغيل الكاميرا</button>\n        <button id=\"stopBtn\" class=\"secondary\">إيقاف</button>\n        <button id=\"torchBtn\" class=\"secondary\">فلاش</button>\n      </div>\n      <div id=\"secureNotice\" class=\"notice\" hidden>يجب فتح UniScan من رابط HTTPS حتى تعمل الكاميرا.</div>\n    </section>\n\n    <section class=\"card\">\n      <div class=\"label\">آخر قراءة</div>\n      <div id=\"lastValue\" class=\"last-value\">—</div>\n      <div id=\"deliveryState\" class=\"delivery muted\">لم تُرسل قراءة بعد.</div>\n      <div class=\"settings-row\">\n        <label for=\"suffix\">بعد القراءة</label>\n        <select id=\"suffix\">\n          <option value=\"ENTER\">Enter</option>\n          <option value=\"TAB\">Tab</option>\n          <option value=\"NONE\">بدون زر</option>\n        </select>\n        <button id=\"copyBtn\" class=\"secondary\">نسخ</button>\n      </div>\n    </section>\n\n    <section class=\"card\">\n      <div class=\"section-head\"><h2>آخر القراءات</h2><button id=\"clearBtn\" class=\"text-btn\">مسح السجل</button></div>\n      <div id=\"history\" class=\"history\"><div class=\"muted\">لا توجد قراءات بعد.</div></div>\n    </section>\n\n    <section class=\"card install-card\">\n      <div><b>ثبّت UniScan على الهاتف</b><div class=\"muted\">يظهر كأنه تطبيق مستقل ويمكن فتحه من الشاشة الرئيسية.</div></div>\n      <button id=\"installBtn\" class=\"secondary\" hidden>تثبيت</button>\n    </section>\n  </main>\n  <div id=\"toast\" class=\"toast\"></div>\n  <script src=\"https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js\"></script>\n  <script src=\"/app.js\"></script>\n</body>\n</html>\n";
const STYLES_CSS = ":root{font-family:Inter,system-ui,-apple-system,\"Segoe UI\",Tahoma,Arial,sans-serif;color:#132019;background:#f2f6f3;--green:#0a7a35;--green2:#13a34e;--line:#dfe8e1;--muted:#68746c;--card:#fff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 50% -20%,#dff5e6 0,#f2f6f3 36%,#eef3ef 100%);min-height:100vh}.app{width:min(760px,100%);margin:auto;padding:18px 14px 42px}.topbar{display:flex;align-items:center;justify-content:space-between;gap:14px;margin:4px 2px 18px}.brand{display:flex;align-items:center;gap:12px;min-width:0}.brand img{width:54px;height:54px;object-fit:contain;border-radius:14px;background:white;box-shadow:0 5px 18px #18351f14}.brand h1{font-size:26px;line-height:1;margin:0}.brand-copy{min-width:0}.credit{display:flex;align-items:center;gap:6px;margin-top:7px;font-size:11px;color:var(--muted);white-space:nowrap}.credit a{color:var(--green);text-decoration:none;font-weight:700;direction:ltr}.credit-dot{opacity:.55}.pill{font-size:12px;border:1px solid var(--line);background:#fff;color:#66726a;border-radius:999px;padding:8px 11px;white-space:nowrap}.pill.ok{background:#e9f8ef;border-color:#bfe8cd;color:#087332}.pill.warn{background:#fff8e8;border-color:#f2dfad;color:#8a6412}.card{background:rgba(255,255,255,.97);border:1px solid var(--line);border-radius:22px;padding:17px;margin:0 0 14px;box-shadow:0 14px 44px #1748220c}.card h2{font-size:17px;margin:0 0 5px}.muted,.hint{color:var(--muted);font-size:13px;line-height:1.55}.pair-row{display:flex;gap:9px;margin-top:12px}.pair-row input{flex:1;text-align:center;direction:ltr;letter-spacing:2px;text-transform:uppercase;font-weight:800}.controls,.settings-row,.install-card,.section-head{display:flex;align-items:center;gap:9px}.controls{margin-top:13px}.grow{flex:1}button,input,select{font:inherit;border-radius:13px;border:1px solid #cfdad1;min-height:46px;padding:0 14px;background:#fff;color:#17211a;outline:none}input:focus,select:focus{border-color:#6ab987;box-shadow:0 0 0 3px #0a7a3514}.primary{border-color:var(--green);background:var(--green);color:white;font-weight:750}.primary:active{background:#075f2a}.secondary{background:#f7faf8;font-weight:650}.text-btn{border:0;background:transparent;color:var(--green);padding:4px;min-height:auto}.camera-shell{position:relative;background:#050806;border-radius:18px;overflow:hidden;min-height:360px;aspect-ratio:4/5}.camera-shell #reader{width:100%;height:100%}.camera-shell video{width:100%!important;height:100%!important;object-fit:cover!important}.camera-shell img{display:none!important}.scan-frame{position:absolute;pointer-events:none;left:8%;right:8%;top:36%;height:28%;border:2px solid #58e487;border-radius:18px;box-shadow:0 0 0 9999px #0000004d}.scan-frame i{position:absolute;left:8%;right:8%;height:2px;top:50%;background:#5cf18b;box-shadow:0 0 12px #5cf18b;animation:scan 2s ease-in-out infinite}@keyframes scan{0%,100%{transform:translateY(-48px);opacity:.5}50%{transform:translateY(48px);opacity:1}}.camera-status{position:absolute;bottom:12px;left:50%;transform:translateX(-50%);background:#07150dc9;color:white;padding:7px 10px;border-radius:999px;font-size:12px;white-space:nowrap}.notice{margin-top:12px;background:#fff5db;color:#79550a;border:1px solid #f3dda5;padding:11px;border-radius:12px;font-size:13px}.label{color:var(--muted);font-size:12px}.last-value{font:800 24px ui-monospace,SFMono-Regular,Consolas,monospace;direction:ltr;text-align:left;word-break:break-all;margin:6px 0}.delivery{margin-bottom:12px}.delivery.ok{color:#087332}.delivery.bad{color:#a7352a}.settings-row{border-top:1px solid #edf1ee;padding-top:13px}.settings-row label{font-size:13px;color:var(--muted)}.settings-row select{flex:1}.section-head{justify-content:space-between;margin-bottom:8px}.section-head h2{margin:0}.history{display:grid;gap:7px}.hist{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 11px;border-radius:12px;background:#f6f9f7}.hist code{direction:ltr;text-align:left;font-weight:750;overflow-wrap:anywhere}.hist span{font-size:11px;color:var(--muted);white-space:nowrap}.install-card{justify-content:space-between}.toast{position:fixed;z-index:20;left:50%;bottom:26px;transform:translate(-50%,20px);opacity:0;pointer-events:none;background:#132019;color:#fff;padding:11px 15px;border-radius:13px;font-size:13px;transition:.2s}.toast.show{opacity:1;transform:translate(-50%,0)}@media(max-width:520px){.credit{font-size:10.5px;gap:4px;flex-wrap:wrap;row-gap:2px}.credit-dot{display:none}.camera-shell{min-height:330px}.controls{display:grid;grid-template-columns:1fr 1fr}.controls .grow{grid-column:1/3}.settings-row{flex-wrap:wrap}.settings-row select{min-width:130px}.pair-row{flex-direction:column}.pair-row button{width:100%}}\n";
const APP_JS = "const $ = (s) => document.querySelector(s);\nconst state = {\n  scanner: null, running: false, ws: null, connected: false, receiver: false,\n  room: \"\", last: \"\", lastAt: 0, reconnectTimer: null, keepAlive: null,\n  deferredPrompt: null, pending: new Map(),\n  history: JSON.parse(localStorage.getItem(\"uniscan_history_v2\") || \"[]\")\n};\n\nfunction toast(text) {\n  const el = $(\"#toast\"); el.textContent = text; el.classList.add(\"show\");\n  clearTimeout(el._t); el._t = setTimeout(() => el.classList.remove(\"show\"), 1500);\n}\nfunction roomValid(v){ return /^[A-Z2-9]{8}$/.test(v); }\nfunction setConn(text, kind=\"\") { const p=$(\"#connPill\"); p.textContent=text; p.className=`pill ${kind}`.trim(); }\nfunction setPairMessage(text){ $(\"#pairMsg\").textContent=text; }\nfunction renderHistory(){\n  const el=$(\"#history\"); el.innerHTML=\"\";\n  if(!state.history.length){ el.innerHTML='<div class=\"muted\">لا توجد قراءات بعد.</div>'; return; }\n  state.history.slice(0,12).forEach(x=>{ const row=document.createElement(\"div\"); row.className=\"hist\";\n    const code=document.createElement(\"code\"); code.textContent=x.value;\n    const time=document.createElement(\"span\"); time.textContent=new Date(x.at).toLocaleTimeString([], {hour:\"2-digit\",minute:\"2-digit\",second:\"2-digit\"});\n    row.append(code,time); el.appendChild(row); });\n}\nfunction remember(value){ state.history.unshift({value,at:Date.now()}); state.history=state.history.slice(0,40); localStorage.setItem(\"uniscan_history_v2\",JSON.stringify(state.history)); renderHistory(); }\nfunction beep(ok=true){ try{const A=window.AudioContext||window.webkitAudioContext,a=new A(),o=a.createOscillator(),g=a.createGain();o.connect(g);g.connect(a.destination);o.frequency.value=ok?980:280;g.gain.value=.035;o.start();setTimeout(()=>{o.stop();a.close()},90)}catch{} }\nfunction relayURL(room){ const proto=location.protocol===\"https:\"?\"wss:\":\"ws:\"; return `${proto}//${location.host}/ws?room=${encodeURIComponent(room)}&role=mobile`; }\nfunction clearSocket(){\n  if(state.reconnectTimer){clearTimeout(state.reconnectTimer);state.reconnectTimer=null}\n  if(state.keepAlive){clearInterval(state.keepAlive);state.keepAlive=null}\n  if(state.ws){ try{state.ws.onclose=null;state.ws.close()}catch{} state.ws=null; }\n  state.connected=false; state.receiver=false;\n}\nfunction connect(room){\n  room=(room||\"\").trim().toUpperCase();\n  if(!roomValid(room)){ toast(\"كود الربط يجب أن يكون 8 أحرف\"); return; }\n  clearSocket(); state.room=room; localStorage.setItem(\"uniscan_room\",room); $(\"#pairCode\").value=room;\n  setConn(\"جاري الاتصال…\",\"warn\"); setPairMessage(\"جاري الاتصال بالحاسبة…\");\n  let ws;\n  try{ ws=new WebSocket(relayURL(room)); }catch{ setConn(\"تعذر الاتصال\"); return; }\n  state.ws=ws;\n  ws.onopen=()=>{\n    state.connected=true; setConn(\"متصل بالسحابة\",\"warn\"); setPairMessage(\"تم الاتصال. بانتظار UniScan على الحاسبة.\");\n    state.keepAlive=setInterval(()=>{try{if(ws.readyState===1)ws.send(\"ping\")}catch{}},20000);\n  };\n  ws.onmessage=(ev)=>{\n    if(ev.data===\"pong\")return;\n    let m; try{m=JSON.parse(ev.data)}catch{return}\n    if(m.type===\"state\"){\n      state.receiver=!!(m.desktop||m.browser);\n      if(state.receiver){setConn(m.desktop?\"الحاسبة مرتبطة\":\"المتصفح مرتبط\",\"ok\");setPairMessage(\"تم الربط بنجاح. شغّل الكاميرا وابدأ المسح.\");}\n      else {setConn(\"بانتظار الحاسبة\",\"warn\");setPairMessage(\"الكود صحيح، لكن Receiver غير متصل حالياً.\");}\n    }\n    if(m.type===\"ack\"){\n      const pending=state.pending.get(m.id); if(pending) state.pending.delete(m.id);\n      if(m.ok){$(\"#deliveryState\").textContent=`تم الإدخال على ${m.via===\"browser\"?\"المتصفح\":\"الحاسبة\"} ✓`;$(\"#deliveryState\").className=\"delivery ok\";}\n      else {$(\"#deliveryState\").textContent=m.error===\"no_receiver\"?\"لا يوجد Receiver متصل\":\"تعذر الإدخال\";$(\"#deliveryState\").className=\"delivery bad\";beep(false)}\n    }\n  };\n  ws.onclose=()=>{\n    state.connected=false; state.receiver=false; setConn(\"انقطع الاتصال\"); setPairMessage(\"سأحاول إعادة الاتصال تلقائياً…\");\n    if(state.keepAlive){clearInterval(state.keepAlive);state.keepAlive=null}\n    state.reconnectTimer=setTimeout(()=>connect(state.room),2200);\n  };\n  ws.onerror=()=>{};\n}\nasync function sendScan(value){\n  value=String(value||\"\").trim(); if(!value)return;\n  const now=Date.now(); if(value===state.last && now-state.lastAt<1200)return;\n  state.last=value; state.lastAt=now; $(\"#lastValue\").textContent=value; remember(value); if(navigator.vibrate)navigator.vibrate(45); beep(true);\n  if(!state.ws||state.ws.readyState!==1){$(\"#deliveryState\").textContent=\"تمت القراءة لكن الاتصال غير متوفر\";$(\"#deliveryState\").className=\"delivery bad\";return}\n  const id=(crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`);\n  state.pending.set(id,Date.now());\n  state.ws.send(JSON.stringify({type:\"scan\",id,value,suffix:$(\"#suffix\").value}));\n  $(\"#deliveryState\").textContent=\"تم الإرسال، بانتظار التأكيد…\"; $(\"#deliveryState\").className=\"delivery muted\";\n  setTimeout(()=>{if(state.pending.has(id)){state.pending.delete(id);$(\"#deliveryState\").textContent=\"لم يصل تأكيد من الحاسبة\";$(\"#deliveryState\").className=\"delivery bad\"}},4500);\n}\nasync function startCamera(){\n  if(!window.isSecureContext){$(\"#secureNotice\").hidden=false;toast(\"افتح UniScan عبر HTTPS\");return}\n  if(state.running)return;\n  if(typeof Html5Qrcode===\"undefined\"){toast(\"تعذر تحميل محرك الباركود\");return}\n  try{\n    state.scanner=new Html5Qrcode(\"reader\");\n    await state.scanner.start({facingMode:{exact:\"environment\"}}, {fps:14,qrbox:(w,h)=>({width:Math.min(w*.88,520),height:Math.min(h*.3,190)}),aspectRatio:1.3333}, sendScan, ()=>{}).catch(async()=>{\n      return state.scanner.start({facingMode:\"environment\"},{fps:12,qrbox:{width:280,height:140}},sendScan,()=>{});\n    });\n    state.running=true; $(\"#cameraStatus\").textContent=\"جاهز للمسح\";\n  }catch(e){console.error(e);$(\"#cameraStatus\").textContent=\"تعذر تشغيل الكاميرا\";toast(\"اسمح للكاميرا ثم حاول مرة أخرى\")}\n}\nasync function stopCamera(){ if(!state.scanner||!state.running)return; try{await state.scanner.stop();state.scanner.clear()}catch{} state.running=false; $(\"#cameraStatus\").textContent=\"الكاميرا متوقفة\"; }\nasync function torch(){ if(!state.running||!state.scanner){toast(\"شغّل الكاميرا أولاً\");return} try{await state.scanner.applyVideoConstraints({advanced:[{torch:true}]});toast(\"تم تشغيل الفلاش\")}catch{toast(\"الفلاش غير مدعوم على هذا الجهاز\")} }\n\n$(\"#pairBtn\").onclick=()=>connect($(\"#pairCode\").value);\n$(\"#pairCode\").addEventListener(\"input\",e=>e.target.value=e.target.value.toUpperCase().replace(/[^A-Z2-9]/g,\"\").slice(0,8));\n$(\"#pairCode\").addEventListener(\"keydown\",e=>{if(e.key===\"Enter\")connect(e.target.value)});\n$(\"#startBtn\").onclick=startCamera; $(\"#stopBtn\").onclick=stopCamera; $(\"#torchBtn\").onclick=torch;\n$(\"#copyBtn\").onclick=async()=>{if(!state.last)return;try{await navigator.clipboard.writeText(state.last);toast(\"تم النسخ\")}catch{}};\n$(\"#clearBtn\").onclick=()=>{state.history=[];localStorage.removeItem(\"uniscan_history_v2\");renderHistory();toast(\"تم مسح السجل\")};\nwindow.addEventListener(\"beforeinstallprompt\",e=>{e.preventDefault();state.deferredPrompt=e;$(\"#installBtn\").hidden=false});\n$(\"#installBtn\").onclick=async()=>{if(!state.deferredPrompt)return;state.deferredPrompt.prompt();await state.deferredPrompt.userChoice;state.deferredPrompt=null;$(\"#installBtn\").hidden=true};\nif(\"serviceWorker\" in navigator) window.addEventListener(\"load\",()=>navigator.serviceWorker.register(\"/sw.js\").catch(()=>{}));\nif(!window.isSecureContext)$(\"#secureNotice\").hidden=false;\nrenderHistory();\nconst params=new URLSearchParams(location.search); const initial=(params.get(\"pair\")||localStorage.getItem(\"uniscan_room\")||\"\").toUpperCase();\nif(roomValid(initial)){ $(\"#pairCode\").value=initial; connect(initial); }\n";
const SW_JS = "const CACHE=\"uniscan-v2.3.0\";\nconst CORE=[\"/\",\"/index.html\",\"/styles.css\",\"/app.js\",\"/manifest.webmanifest\",\"/logo.png\",\"/icons/icon-192.png\",\"/icons/icon-512.png\"];\nself.addEventListener(\"install\",e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(CORE)).then(()=>self.skipWaiting())));\nself.addEventListener(\"activate\",e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));\nself.addEventListener(\"fetch\",e=>{\n  const req=e.request; if(req.method!==\"GET\")return;\n  const u=new URL(req.url); if(u.pathname===\"/ws\")return;\n  e.respondWith(caches.match(req).then(hit=>hit||fetch(req).then(res=>{const copy=res.clone();caches.open(CACHE).then(c=>c.put(req,copy)).catch(()=>{});return res}).catch(()=>caches.match(\"/index.html\"))));\n});\n";
const MANIFEST = "{\n  \"name\": \"UniScan - Universal Mobile Barcode Scanner\",\n  \"short_name\": \"UniScan\",\n  \"description\": \"حوّل هاتفك إلى قارئ باركود لاسلكي للحاسبة.\",\n  \"id\": \"/\",\n  \"start_url\": \"/\",\n  \"scope\": \"/\",\n  \"display\": \"standalone\",\n  \"background_color\": \"#f2f6f3\",\n  \"theme_color\": \"#0b7a33\",\n  \"orientation\": \"portrait-primary\",\n  \"icons\": [\n    {\"src\":\"/icons/icon-192.png\",\"sizes\":\"192x192\",\"type\":\"image/png\",\"purpose\":\"any maskable\"},\n    {\"src\":\"/icons/icon-512.png\",\"sizes\":\"512x512\",\"type\":\"image/png\",\"purpose\":\"any maskable\"}\n  ]\n}\n";
const LOGO_B64 = "";
const ICON192_B64 = "";
const ICON512_B64 = "";

function b64Bytes(s) {
  const raw = atob(s);
  const out = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) out[i] = raw.charCodeAt(i);
  return out;
}

function text(body, type, extra={}) {
  return new Response(body, { headers: { "content-type": type, ...extra } });
}

function png(b64) {
  return new Response(b64Bytes(b64), { headers: { "content-type": "image/png", "cache-control": "public, max-age=604800" } });
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === "/ws") {
      if ((request.headers.get("Upgrade") || "").toLowerCase() !== "websocket") {
        return new Response("WebSocket required", { status: 426 });
      }
      const room = (url.searchParams.get("room") || "").toUpperCase();
      const role = (url.searchParams.get("role") || "").toLowerCase();
      if (!ROOM_RE.test(room) || !ROLES.has(role)) {
        return new Response("Invalid room or role", { status: 400 });
      }
      const id = env.SESSIONS.idFromName(room);
      return env.SESSIONS.get(id).fetch(request);
    }

    if (request.method !== "GET" && request.method !== "HEAD") return new Response("Method not allowed", {status:405});
    switch (url.pathname) {
      case "/":
      case "/index.html": return text(INDEX_HTML, "text/html; charset=utf-8", {"cache-control":"no-cache"});
      case "/styles.css": return text(STYLES_CSS, "text/css; charset=utf-8", {"cache-control":"public, max-age=3600"});
      case "/app.js": return text(APP_JS, "text/javascript; charset=utf-8", {"cache-control":"no-cache"});
      case "/sw.js": return text(SW_JS, "text/javascript; charset=utf-8", {"cache-control":"no-cache", "service-worker-allowed":"/"});
      case "/manifest.webmanifest": return text(MANIFEST, "application/manifest+json; charset=utf-8", {"cache-control":"no-cache"});
      case "/logo.png": return png(LOGO_B64);
      case "/icons/icon-192.png": return png(ICON192_B64);
      case "/icons/icon-512.png": return png(ICON512_B64);
      default: return new Response("Not found", {status:404});
    }
  },
};

export class UniScanSession extends DurableObject {
  constructor(ctx, env) {
    super(ctx, env);
    this.ctx.setWebSocketAutoResponse(new WebSocketRequestResponsePair("ping", "pong"));
  }

  async fetch(request) {
    const url = new URL(request.url);
    const role = (url.searchParams.get("role") || "").toLowerCase();
    if (!ROLES.has(role)) return new Response("Invalid role", { status: 400 });

    for (const old of this.ctx.getWebSockets(role)) {
      try { old.close(4001, "Replaced by a newer UniScan connection"); } catch {}
    }

    const pair = new WebSocketPair();
    const [client, server] = Object.values(pair);
    this.ctx.acceptWebSocket(server, [role]);
    server.serializeAttachment({ role, joinedAt: Date.now() });
    try { server.send(JSON.stringify({ type: "ready", role })); } catch {}
    this.broadcastState();
    return new Response(null, { status: 101, webSocket: client });
  }

  webSocketMessage(ws, message) {
    if (typeof message !== "string") return;
    if (message === "ping") return;
    const meta = ws.deserializeAttachment() || {};
    let data;
    try { data = JSON.parse(message); } catch { return; }

    if (meta.role === "mobile" && data.type === "scan") {
      const value = String(data.value || "").trim();
      const suffix = ["ENTER", "TAB", "NONE"].includes(data.suffix) ? data.suffix : "ENTER";
      const id = String(data.id || crypto.randomUUID()).slice(0, 80);
      if (!value || [...value].length > 4096) {
        this.safeSend(ws, { type: "ack", id, ok: false, error: "invalid_barcode" });
        return;
      }
      const targets = [...this.ctx.getWebSockets("desktop"), ...this.ctx.getWebSockets("browser")];
      if (!targets.length) {
        this.safeSend(ws, { type: "ack", id, ok: false, error: "no_receiver" });
        return;
      }
      const payload = JSON.stringify({ type: "scan", id, value, suffix, at: Date.now() });
      for (const target of targets) { try { target.send(payload); } catch {} }
      return;
    }

    if ((meta.role === "desktop" || meta.role === "browser") && data.type === "ack") {
      const payload = JSON.stringify({
        type: "ack", id: String(data.id || "").slice(0,80), ok: !!data.ok, via: meta.role,
        error: data.error ? String(data.error).slice(0,120) : undefined
      });
      for (const mobile of this.ctx.getWebSockets("mobile")) { try { mobile.send(payload); } catch {} }
    }
  }

  webSocketClose(ws, code, reason) { try { ws.close(code, reason); } catch {} this.broadcastState(); }
  webSocketError(ws) { try { ws.close(1011, "WebSocket error"); } catch {} this.broadcastState(); }

  broadcastState() {
    const raw = JSON.stringify({
      type: "state",
      desktop: this.ctx.getWebSockets("desktop").length > 0,
      mobile: this.ctx.getWebSockets("mobile").length > 0,
      browser: this.ctx.getWebSockets("browser").length > 0
    });
    for (const client of this.ctx.getWebSockets()) { try { client.send(raw); } catch {} }
  }
  safeSend(ws, obj) { try { ws.send(JSON.stringify(obj)); } catch {} }
}
